insert into public.bcps_schools (name, site_url, school_location_nbr, notes)
select v.name, v.url, v.loc, 'Website from the browardschools.com school menu, verified by the site title (2026-10-26)'
from v
where not exists (select 1 from public.bcps_schools s where ltrim(s.school_location_nbr, '0') = ltrim(v.loc, '0'));
